def _dados_iniciais() -> None:
    t_tipo = sa.table("tipo_unidade", *[sa.column(c) for c in (
        "codigo", "nome", "pode_ser_raiz", "possui_eixo", "multinivel", "e_nivel", "e_frente", "cor", "ordem",
        "ativo", "versao")], sa.column("id", sa.Uuid), sa.column("criado_em", sa.DateTime(timezone=True)))
    agora = datetime.now(UTC)
    ids = {c: uuid.uuid4() for c in TIPOS}
    op.bulk_insert(t_tipo, [
        {"id": ids[c], "codigo": c, "nome": n, "pode_ser_raiz": r, "possui_eixo": e, "multinivel": m, "e_nivel": nv,
         "e_frente": f, "cor": cor, "ordem": o, "ativo": True, "criado_em": agora, "versao": 1}
        for c, (n, r, e, m, nv, f, cor, o) in TIPOS.items()
    ])
    t_regra = sa.table("regra_hierarquia", sa.column("tipo_pai_id", sa.Uuid), sa.column("tipo_filho_id", sa.Uuid))
    op.bulk_insert(t_regra, [{"tipo_pai_id": ids[p], "tipo_filho_id": ids[f]} for p, fs in REGRAS.items() for f in fs])

    t_perm = sa.table("permissao", sa.column("id", sa.Uuid), sa.column("codigo"), sa.column("descricao"))
    op.bulk_insert(t_perm, [{"id": uuid.uuid4(), "codigo": c, "descricao": d} for c, (d, _) in PERMISSOES.items()])
    for codigo, (_d, papeis) in PERMISSOES.items():
        lista = ",".join(f"'{p}'" for p in papeis)
        op.execute(sa.text(
            "INSERT INTO papel_permissao (papel_id, permissao_id) "
            f"SELECT p.id, m.id FROM papel p, permissao m WHERE p.codigo IN ({lista}) AND m.codigo = '{codigo}'"))
